PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
SELECT ?song ?p ?o WHERE {
  VALUES ?song { dbr:Come_with_Me_(Pure_Imagination) dbr:Hold_on_Me_(Grinspoon_song) }
  {
    ?song dbo:releaseDate ?o . BIND(dbo:releaseDate AS ?p)
  }
  UNION
  {
    ?song dbp:released ?o . BIND(dbp:released AS ?p)
  }
}

