PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?song ?date WHERE {
  VALUES ?song { <http://dbpedia.org/resource/Come_with_Me_(Pure_Imagination)> <http://dbpedia.org/resource/Hold_on_Me_(Grinspoon_song)> }
  OPTIONAL { ?song dbo:releaseDate ?d1. }
